import{_ as l,r as t,o as r,c as i,e,a as n,s as o,d as s}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Event Handlers - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"AJAX handlers","slug":"ajax-handlers","link":"#ajax-handlers","children":[{"level":3,"title":"Calling a handler","slug":"calling-a-handler","link":"#calling-a-handler","children":[{"level":4,"title":"Generic handler","slug":"generic-handler","link":"#generic-handler","children":[]}]}]},{"level":2,"title":"Redirects in AJAX handlers","slug":"redirects-in-ajax-handlers","link":"#redirects-in-ajax-handlers","children":[]},{"level":2,"title":"Returning data from AJAX handlers","slug":"returning-data-from-ajax-handlers","link":"#returning-data-from-ajax-handlers","children":[]},{"level":2,"title":"Throwing an AJAX exception","slug":"throwing-an-ajax-exception","link":"#throwing-an-ajax-exception","children":[]},{"level":2,"title":"Running code before handlers","slug":"running-code-before-handlers","link":"#running-code-before-handlers","children":[]}],"relativePath":"1.x/ajax/handlers.md","filePath":"1.x/ajax/handlers.md"}'),u={name:"1.x/ajax/handlers.md"};function d(h,a,k,g,m,f){const p=t("pre-heading"),c=t("post-heading");return r(),i("div",null,[e(p),a[0]||(a[0]=n("h1",null,"Event Handlers",-1)),e(c),a[1]||(a[1]=o(`<h2 id="ajax-handlers"><a href="#ajax-handlers" class="header-anchor">#</a> AJAX handlers</h2><p>AJAX event handlers are PHP functions that can be defined in the page or layout <a href="./../cms/themes.html#php-section">PHP section</a> or inside <a href="./../cms/components.html">components</a>. Handler names should have the following pattern: <code>onName</code>. All handlers support the use of <a href="./../ajax/update-partials.html">updating partials</a> as part of the AJAX request.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>If two handlers with the same name are defined in a page and layout together, the page handler will be executed. The handlers defined in <a href="./../cms/components.html">components</a> have the lowest priority.</p><h3 id="calling-a-handler"><a href="#calling-a-handler" class="header-anchor">#</a> Calling a handler</h3><p>Every AJAX request should specify a handler name, either using the <a href="./../ajax/attributes-api.html">data attributes API</a> or the <a href="./../ajax/javascript-api.html">JavaScript API</a>. When the request is made, the server will search all the registered handlers and locate the first one it finds.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- JavaScript API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> $<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If two components register the same handler name, it is advised to prefix the handler with the <a href="./../cms/components.html#components-aliases">component short name or alias</a>. If a component uses an alias of <strong>mycomponent</strong> the handler can be targeted with <code>mycomponent::onName</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mycomponent::onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,9)),a[2]||(a[2]=n("p",null,[s("You may want to use the "),n("a",{href:"https://octobercms.com/docs/plugin/components#referencing-self",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("code",null,"__SELF__"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(" reference variable instead of the hard coded alias in case the user changes the component alias used on the page.")],-1)),a[3]||(a[3]=o(`<div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{{ __SELF__ }}::onCalculate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token punctuation">&#39;</span>{{ __SELF__ }}::calcresult&#39;: &#39;#result&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="generic-handler"><a href="#generic-handler" class="header-anchor">#</a> Generic handler</h4><p>Sometimes you may need to make an AJAX request for the sole purpose of updating page contents, not needing to execute any code. You may use the <code>onAjax</code> handler for this purpose. This handler is available everywhere without needing to write any code.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Do nothing<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="redirects-in-ajax-handlers"><a href="#redirects-in-ajax-handlers" class="header-anchor">#</a> Redirects in AJAX handlers</h2><p>If you need to redirect the browser to another location, return the <code>Redirect</code> object from the AJAX handler. The framework will redirect the browser as soon as the response is returned from the server. Example AJAX handler:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirectMe</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="returning-data-from-ajax-handlers"><a href="#returning-data-from-ajax-handlers" class="header-anchor">#</a> Returning data from AJAX handlers</h2><p>In advanced cases you may want to return structured data from your AJAX handlers. If an AJAX handler returns an array, you can access its elements in the <code>success</code> event handler. Example AJAX handler:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFetchDataFromServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">/* Some server-side code */</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;totalUsers&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1000</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;totalProjects&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">937</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The data can be fetched with the data attributes API:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The same with the JavaScript API:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript"><span class="token function">$</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="throwing-an-ajax-exception"><a href="#throwing-an-ajax-exception" class="header-anchor">#</a> Throwing an AJAX exception</h2><p>You may throw an <a href="./../services/error-log.html#ajax-exception">AJAX exception</a> using the <code>AjaxException</code> class to treat the response as an error while retaining the ability to send response contents as normal. Simply pass the response contents as the first argument of the exception.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;error&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Not enough questions&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;questionsNeeded&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">2</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: When throwing this exception type <a href="./../ajax/update-partials.html">partials will be updated</a> as normal.</p></blockquote><h2 id="running-code-before-handlers"><a href="#running-code-before-handlers" class="header-anchor">#</a> Running code before handlers</h2><p>Sometimes you may want code to execute before a handler executes. Defining an <code>onInit</code> function as part of the <a href="./../cms/layouts.html#dynamic-pages">page execution life cycle</a> allows code to run before every AJAX handler.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a page or layout PHP code section</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may define an <code>init</code> method inside a <a href="./../plugin/components.html#component-initialization">component class</a> or <a href="./../backend/widgets.html">backend widget class</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a component or widget class</span>
<span class="token punctuation">}</span>
</code></pre></div>`,23))])}const w=l(u,[["render",d]]);export{x as __pageData,w as default};
